const iconPaths={back:'M15 5l-7 7 7 7',arrow:'M4 12h15M13 6l6 6-6 6',chevron:'M9 5l7 7-7 7',info:'M12 11v6M12 7h.01|circle:12,12,9',pause:'M9 6v12M15 6v12',play:'M8 5l11 7-11 7z',cup:'M7 3h10v7a5 5 0 01-10 0zM7 5H3v3a4 4 0 004 4M17 5h4v3a4 4 0 01-4 4M12 15v5M7 21h10',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M5 19l1.5-1.5M17.5 6.5L19 5|circle:12,12,4',spark:'M12 2l2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8z',person:'M5 21v-3a7 7 0 0114 0v3|circle:12,7,4',wing:'M3 19c2-11 7-14 18-14l-4 5-4 1 2 2-5 2 1 2-8 2zM3 21l10-10',camera:'M8 6l2-3h4l2 3h4a2 2 0 012 2v11a2 2 0 01-2 2H4a2 2 0 01-2-2V8a2 2 0 012-2z|circle:12,13,4',fast:'M3 5l8 7-8 7zM12 5l8 7-8 7z',skip:'M3 5l10 7-10 7zM17 5v14M21 5v14',menu:'M4 6h16M4 12h16M4 18h16',up:'M5 15l7-7 7 7',flag:'M5 22V3M5 3c5-4 9 4 15 0v10c-6 4-10-4-15 0M10 3v10M15 5v10M5 8c6-4 10 4 15 0',crown:'M3 5l4 5 5-7 5 7 4-5-2 14H5zM6 22h12',replay:'M4 9a8 8 0 111 9M4 3v6h6',check:'M4 12l5 5L20 6',close:'M6 6l12 12M18 6L6 18'};
function renderIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{const name=el.dataset.icon;const def=iconPaths[name]||iconPaths.info;el.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+def.split('|').map(p=>{if(p.startsWith('circle:')){const [cx,cy,r]=p.slice(7).split(',');return `<circle cx="${cx}" cy="${cy}" r="${r}"/>`;}return `<path d="${p}"/>`;}).join('')+'</svg>';});}
const game=document.getElementById('game'), params=new URLSearchParams(location.search), modalLayer=document.getElementById('modal-layer');
let currentScreen='race',speed=1,camera='auto',toastTimer,previousFocus;
const captions={prepare:'01 / 출전 준비',race:'02 / 레이스 관전',result:'03 / 경기 결과'};
const sampleResults=[['루크','기사 · 페코페코','1:34.82'],['레온','기사 · 황금 갈기','1:35.06'],['리나','복사 · 포링','1:35.41'],['카인','기사 · 드래곤','1:36.02'],['유나','검사 · 페코페코','1:36.38'],['아렌','상인 · 포링','1:36.71'],['세라','복사 · 황금 갈기','1:37.15'],['노아','검사 · 페코페코','1:37.84']];
function showScreen(screen){if(!captions[screen])screen='race';closeModal();currentScreen=screen;game.dataset.screen=screen;document.querySelectorAll('.screen').forEach(el=>el.hidden=el.id!==screen);document.querySelectorAll('.screen-nav button').forEach(el=>{el.classList.toggle('active',el.dataset.screen===screen);el.setAttribute('aria-pressed',String(el.dataset.screen===screen));});document.getElementById('screen-caption').textContent=captions[screen];if(screen==='race'){speed=1;document.getElementById('speed-label').textContent='×1';}resize();}
function resize(){const capture=document.body.classList.contains('capture'),mobile=innerWidth<=760;const height=mobile&&!capture?Math.max(1280,Math.round(innerHeight*720/innerWidth)):Number(document.getElementById('ratio').value);document.documentElement.style.setProperty('--game-height',height+'px');game.classList.toggle('narrow',innerWidth<360);if(capture)return;const scale=mobile?innerWidth/720:Math.min((innerHeight-100)/height,(innerWidth<1050?innerWidth-410:innerWidth-560)/720,.66);const finalScale=Math.max(.25,scale);game.style.transform=`scale(${finalScale})`;const frame=document.querySelector('.phone-frame');frame.style.width=720*finalScale+'px';frame.style.height=height*finalScale+'px';}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,2600);}
function openModal(title,content,actions){previousFocus=document.activeElement;document.getElementById('modal-title').textContent=title;document.getElementById('modal-content').innerHTML=content;document.getElementById('modal-actions').innerHTML=actions||'<button class="button primary" data-action="close">확인</button>';modalLayer.hidden=false;renderIcons(modalLayer);modalLayer.querySelector('button').focus({preventScroll:true});}
function closeModal(){modalLayer.hidden=true;if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});previousFocus=null;}
const detail=(label,value)=>`<div class="detail-row"><small>${label}</small><strong>${value}</strong></div>`;
function act(action){switch(action){case'back':openModal('출전 대기','<p>프론테라 초원컵에 출전할 준비가 되었습니다.</p>','<button class="button primary" data-action="close">출전 준비로 돌아가기</button>');break;case'course':openModal('프론테라 초원컵',detail('코스','잔디 · 오른쪽 방향')+detail('거리','1,600 m')+detail('날씨 / 노면','맑음 / 양호')+detail('출전 번호','03'));break;case'rider':openModal('루크 & 페코페코',detail('직업','기사 · Lv. 24')+detail('탈것 / 교감','페코페코 · Lv. 8')+detail('스피드 / 지구력 / 파워','684 / 592 / 621')+'<p>자동 발동 스킬<br><strong>페코페코의 질주</strong></p><p>경기 중 스킬 발동 시 알림으로 표시됩니다.</p>');break;case'camera':camera=camera==='auto'?'follow':'auto';game.classList.toggle('camera-manual',camera==='follow');document.getElementById('camera-label').textContent=camera==='auto'?'자동 카메라':'내 주자 추적';toast(camera==='auto'?'자동 카메라로 전환했습니다':'루크를 추적합니다');break;case'speed':speed=speed===1?2:speed===2?4:1;document.getElementById('speed-label').textContent='×'+speed;toast('관전 배속 ×'+speed);break;case'skip':openModal('결과까지 이동','<p>남은 레이스 연출을 건너뛰고<br>경기 결과를 확인할까요?</p>','<button class="button primary" data-screen="result">결과 확인<i data-icon="arrow"></i></button><button class="button secondary" data-action="close">계속 관전</button>');break;case'pause':openModal('잠시 쉬어가기','<p>레이스 관전을 일시정지했습니다.</p>','<button class="button primary" data-action="close"><i data-icon="play"></i>계속 관전</button><button class="button secondary" data-action="skip">결과까지 이동</button>');break;case'menu':openModal('관전 설정','<label class="toggle-row">스킬 발동 알림<input type="checkbox" id="skill-toggle" '+(!document.querySelector('.skill-notice').hidden?'checked':'')+'></label><label class="toggle-row">중계 문구<input type="checkbox" id="comment-toggle" '+(!document.querySelector('.commentary').hidden?'checked':'')+'></label>','<button class="button primary" data-action="save-settings">적용하고 계속 관전</button>');break;case'save-settings':document.querySelector('.skill-notice').hidden=!document.getElementById('skill-toggle').checked;document.querySelector('.commentary').hidden=!document.getElementById('comment-toggle').checked;closeModal();break;case'results':openModal('전체 경기 결과',sampleResults.map((r,i)=>`<div class="ranking-row ${i===0?'self':''}"><b>${i+1}</b><div><strong>${r[0]}</strong><span>${r[1]}</span></div><time>${r[2]}</time></div>`).join(''));break;case'replay':showScreen('race');toast('레이스 장면을 다시 확인합니다');break;case'close':closeModal();break;}}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.screen){showScreen(button.dataset.screen);return;}if(button.dataset.action)act(button.dataset.action);});
document.addEventListener('keydown',event=>{if(modalLayer.hidden)return;if(event.key==='Escape')closeModal();if(event.key==='Tab'){const items=[...modalLayer.querySelectorAll('button,input')].filter(el=>!el.hidden&&!el.disabled);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.getElementById('ratio').addEventListener('change',resize);document.getElementById('safe-toggle').addEventListener('change',event=>game.classList.toggle('show-safe',event.target.checked));window.addEventListener('resize',resize);
if(params.has('capture'))document.body.classList.add('capture');if(params.has('overlay'))document.body.classList.add('ui-only');if(params.get('height')==='1600')document.getElementById('ratio').value='1600';if(params.has('safe')){game.classList.add('show-safe');document.getElementById('safe-toggle').checked=true;}renderIcons();showScreen(params.get('screen')||'race');
